def _child_seed(seed: int | None, i: int) -> int | None:
    "The seed of the `i`-th part of something seeded with `seed` (None: unseeded)."
    return None if seed is None else int(np.random.SeedSequence([seed, i]).generate_state(1)[0])


def _shape(x):
    "The shapes of the inputs, nested like them (for `build`)."
    if hasattr(x, 'shape'):
        return tuple(x.shape)
    if isinstance(x, (list, tuple)):
        return type(x)(_shape(v) for v in x) if type(x) in (list, tuple) else ()
    if isinstance(x, dict):
        return {k: _shape(v) for k, v in x.items()}
    return ()


def _is_torch(x) -> bool:
    "Whether `x` is a torch tensor (without importing torch)."
    return type(x).__module__.partition('.')[0] == 'torch'


def _full(like, value, boolean: bool = False):
    "An array (or tensor) shaped like `like`, filled with `value`."
    if _is_torch(like):
        import torch
        return torch.full_like(like, value, dtype=torch.bool if boolean else None)
    return np.full(np.shape(like), value, dtype=bool if boolean else float)


def _params(f) -> tuple:
    "The named parameters of `f` (of a method, without `self`: cached per function, as blocks are called often)."
    func = getattr(f, '__func__', None)
    if func is None:
        return tuple(p for p in inspect.signature(f).parameters.values() if p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD))
    return _method_params(func)


@functools.lru_cache(maxsize=None)
def _method_params(func) -> tuple:
    return tuple(p for p in list(inspect.signature(func).parameters.values())[1:]
                 if p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD))

